item.text:
{
  "gaps": [
    {
      "concept": "Sperm capacitation enables the acrosome reaction; acrosomal enzymes penetrate the zona pellucida.",
      "why_tested": "Identifies the fertilization step disrupted when sperm cannot penetrate the oocyte.",
      "yield": "mid"
    },
    {
      "concept": "The oocyte’s cortical reaction modifies the zona pellucida and blocks polyspermy.",
      "why_tested": "Explains how fertilization normally prevents entry of a second sperm.",
      "yield": "mid"
    },
    {
      "concept": "The secondary oocyte remains arrested in metaphase II until fertilization triggers completion of meiosis II.",
      "why_tested": "Identifies the meiotic stage of the ovulated oocyte.",
      "yield": "mid"
    },
    {
      "concept": "Cleavage produces a morula around day 3 and a blastocyst around day 5; the blastocyst sheds its zona pellucida before implantation.",
      "why_tested": "Tests the order of early developmental stages and the prerequisite for implantation.",
      "yield": "hi"
    },
    {
      "concept": "The blastocyst’s inner cell mass forms the embryo; its outer trophoblast contributes to the placenta.",
      "why_tested": "Asks which blastocyst cell population gives rise to embryonic versus placental tissue.",
      "yield": "hi"
    },
    {
      "concept": "During gastrulation, epiblast cells migrate through the primitive streak to form endoderm and mesoderm; remaining epiblast becomes ectoderm.",
      "why_tested": "Tests the cellular origin of all three definitive germ layers.",
      "yield": "hi"
    },
    {
      "concept": "Persistent primitive streak cells can form a sacrococcygeal teratoma containing tissues from multiple germ layers.",
      "why_tested": "Explains a neonatal sacrococcygeal mass with several tissue types.",
      "yield": "mid"
    },
    {
      "concept": "The fetal period begins in week 9 and is characterized mainly by growth and functional maturation.",
      "why_tested": "Distinguishes effects of later fetal exposures from structural defects during organogenesis.",
      "yield": "mid"
    },
    {
      "concept": "The yolk sac is the first site of hematopoiesis and an early source of primordial germ cells.",
      "why_tested": "Identifies the extraembryonic structure responsible for early blood formation or germ-cell origin.",
      "yield": "hi"
    },
    {
      "concept": "Epiblast forms the amnion; hypoblast forms the yolk-sac lining; trophoblast and extraembryonic mesoderm form the chorion.",
      "why_tested": "Matches extraembryonic membranes to their embryologic sources.",
      "yield": "mid"
    },
    {
      "concept": "Ruptured amnion can produce fibrous bands that cause asymmetric limb constrictions or amputations.",
      "why_tested": "Explains irregular fetal limb defects without a Mendelian pattern.",
      "yield": "mid"
    },
    {
      "concept": "Fetal capillaries lie within chorionic villi; maternal blood surrounds the villi, so the two circulations usually remain separate.",
      "why_tested": "Tests the path of maternal–fetal exchange on a placental diagram or histologic section.",
      "yield": "hi"
    },
    {
      "concept": "Primary villi contain trophoblast, secondary villi acquire mesoderm, and tertiary villi develop fetal blood vessels.",
      "why_tested": "Identifies the developmental stage at which chorionic villi establish fetal circulation.",
      "yield": "mid"
    },
    {
      "concept": "Extravillous trophoblast remodels maternal spiral arteries into low-resistance vessels; shallow invasion contributes to preeclampsia and fetal growth restriction.",
      "why_tested": "Links abnormal placentation to maternal hypertension or reduced fetal perfusion.",
      "yield": "hi"
    },
    {
      "concept": "Maternal IgG crosses the placenta through Fc receptors; IgM generally does not.",
      "why_tested": "Distinguishes passive fetal immunity from fetal IgM production after intrauterine infection.",
      "yield": "hi"
    },
    {
      "concept": "hPL reduces maternal glucose use and promotes fat use, increasing glucose availability to the fetus.",
      "why_tested": "Explains the fetal advantage of pregnancy-associated maternal insulin resistance.",
      "yield": "mid"
    },
    {
      "concept": "Progesterone maintains the decidua and suppresses uterine contractions during pregnancy.",
      "why_tested": "Asks how corpus-luteum or placental progesterone supports an established pregnancy.",
      "yield": "mid"
    },
    {
      "concept": "Tubal ectopic pregnancy most often implants in the ampulla; prior pelvic inflammatory disease or tubal surgery increases risk.",
      "why_tested": "Explains early pregnancy with pelvic pain and bleeding after tubal damage.",
      "yield": "hi"
    },
    {
      "concept": "Ectopic pregnancy can show a positive β-hCG test, slower-than-expected β-hCG rise, and no intrauterine gestational sac on ultrasound.",
      "why_tested": "Distinguishes ectopic implantation from a normally developing intrauterine pregnancy.",
      "yield": "hi"
    },
    {
      "concept": "Methotrexate inhibits dihydrofolate reductase and can treat a stable, unruptured ectopic pregnancy.",
      "why_tested": "Connects an antifolate drug mechanism to treatment of tubal trophoblast.",
      "yield": "mid"
    },
    {
      "concept": "Placenta previa covers the internal cervical os and classically causes painless third-trimester bleeding.",
      "why_tested": "Distinguishes low placental implantation from painful placental abruption.",
      "yield": "hi"
    },
    {
      "concept": "Placenta accreta follows deficient decidua basalis, often at a cesarean scar; villi adhere to myometrium and the placenta fails to separate.",
      "why_tested": "Explains retained placenta and severe postpartum hemorrhage after prior uterine surgery.",
      "yield": "hi"
    },
    {
      "concept": "In placenta increta, villi invade myometrium; in percreta, they penetrate through the uterine wall.",
      "why_tested": "Distinguishes placental invasion depth from a pathology description.",
      "yield": "mid"
    },
    {
      "concept": "Placental abruption is premature placental separation, causing painful bleeding and a tender uterus; hypertension and cocaine are risk factors.",
      "why_tested": "Separates abruption from previa in a late-pregnancy bleeding vignette.",
      "yield": "hi"
    },
    {
      "concept": "Vasa previa involves unprotected fetal vessels over the cervical os; membrane rupture causes painless bleeding with fetal distress.",
      "why_tested": "Distinguishes fetal-vessel bleeding from maternal bleeding due to placenta previa.",
      "yield": "mid"
    },
    {
      "concept": "Twin–twin transfusion results from vascular anastomoses in a shared placenta: the donor develops anemia and oligohydramnios; the recipient develops polycythemia and polyhydramnios.",
      "why_tested": "Interprets discordant amniotic fluid and blood findings in monochorionic twins.",
      "yield": "hi"
    },
    {
      "concept": "Monoamniotic twins share one amniotic sac and are vulnerable to umbilical cord entanglement.",
      "why_tested": "Identifies the distinctive complication of twins with no dividing membrane.",
      "yield": "mid"
    },
    {
      "concept": "A thick intertwin membrane with a lambda sign suggests dichorionic twins; a thin membrane with a T sign suggests monochorionic twins.",
      "why_tested": "Determines chorionicity from a twin ultrasound.",
      "yield": "mid"
    },
    {
      "concept": "Oligohydramnios can cause pulmonary hypoplasia, flattened facies, and limb deformities as components of Potter sequence.",
      "why_tested": "Recognizes the fetal consequences of prolonged low amniotic fluid.",
      "yield": "hi"
    },
    {
      "concept": "Complete hydatidiform mole is androgenetic diploid, with diffuse swollen villi, marked trophoblast proliferation, and no fetus.",
      "why_tested": "Explains very high β-hCG, absent fetal tissue, and a cystic placental appearance.",
      "yield": "hi"
    },
    {
      "concept": "Partial hydatidiform mole is usually diandric triploid, with focal villous swelling and possible fetal tissue.",
      "why_tested": "Distinguishes partial from complete mole using karyotype and pathology.",
      "yield": "hi"
    }
  ]
}
